fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    let m = a.len();
    let n = b.len();
    debug_assert!(m > 0 && n > 0);
    debug_assert!(m == n || m == 1 || n == 1);

    let out_len = m.max(n);

    let out_a = if m == out_len {
        a
    } else {
        vec![a[0]; out_len]
    };

    let out_b = if n == out_len {
        b
    } else {
        vec![b[0]; out_len]
    };

    (out_a, out_b)
}